/**
 * Docs: docs/scripts/seed.md
 * SQL seed executor for the Decoder Ring
 *
 * Reads one catalog's SQL files from prisma/seed-sql/<catalog>/ in alphabetical
 * order and executes each against the database via psql.
 *
 * The catalog is declared, never inferred: SEED_CATALOG=<name> or --catalog=<name>.
 *
 * SQL files are generated by: yarn seed:generate
 */

import { join, dirname } from "node:path";
import { execFileSync, execSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import {
  requestedCatalog,
  resolveCatalogDir,
  seedFilesIn,
} from "./catalog-dir.js";
import {
  databaseNameOf,
  devContainerPorts,
  devContainerTarget,
  psqlConnection,
  psqlFailure,
} from "./docker-psql-target.js";
import { seedProgress } from "./seed-progress.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Why a file goes to psql rather than through the dev container.
const PSQL_BECAUSE = {
  elsewhere: "Using psql against the URL's host...",
  "not-identifier":
    "The URL's role or database is not a plain identifier, using local psql...",
  "no-docker": "Docker unavailable, using local psql...",
} as const;

function main(): void {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    throw new Error("DATABASE_URL environment variable is required");
  }

  // Named in the log when the URL parses; a URL psql accepts but Node does not is never
  // printed, since it may carry a password.
  const database = databaseNameOf(dbUrl);
  const catalog = requestedCatalog();
  // The dev container takes the seed only when DATABASE_URL names it: this machine, on
  // the port it publishes. Any other URL, another host or a scratch database on another
  // local port, goes to psql, so the container never takes a seed meant for elsewhere.
  // Decided once for the whole run. Only the container path interpolates the role and
  // database into a shell command, so only it holds them to plain identifiers; a name it
  // refuses goes to psql, which takes the URL as written.
  const route = devContainerTarget(dbUrl, devContainerPorts());
  const psql = psqlConnection(dbUrl);
  const seedDir = resolveCatalogDir(join(__dirname, "seed-sql"), catalog);
  const files = seedFilesIn(seedDir);

  console.log(
    `Seeding catalog "${catalog}" into ${database ? `database "${database}"` : "the database DATABASE_URL names"} — ${files.length} SQL files...`,
  );

  for (const [i, file] of files.entries()) {
    const filePath = join(seedDir, file);
    console.log(`  Running ${file}...`);
    try {
      runFile(file, filePath);
    } catch (err) {
      console.error(`  ${seedProgress(files, i)}`);
      throw err;
    }
  }

  console.log("Seed completed successfully.");

  function runFile(file: string, filePath: string): void {
    // On the container route, a failed `docker cp` means Docker or the container went away
    // since the run began, and the file goes to psql instead. A SQL error must NOT be
    // silently swallowed, so psql runs with ON_ERROR_STOP=1 and inherits stderr — an error
    // then aborts the seed loudly.
    const containerPath = `/tmp/${file}`;
    let container = route.via === "container" ? route : null;
    // Read only once the file goes to psql: the route's reason, or Docker gone mid-run.
    const because: keyof typeof PSQL_BECAUSE =
      route.via === "psql" ? route.reason : "no-docker";
    if (container) {
      try {
        execSync(
          `docker cp "${filePath}" zt-decoder-ring-db:${containerPath}`,
          {
            stdio: ["ignore", "pipe", "pipe"],
          },
        );
      } catch {
        container = null;
      }
    }

    if (container) {
      try {
        execSync(
          `docker exec zt-decoder-ring-db psql -U ${container.user} -d ${container.database} -v ON_ERROR_STOP=1 -f ${containerPath}`,
          { stdio: ["ignore", "pipe", "inherit"] },
        );
      } finally {
        execSync(`docker exec zt-decoder-ring-db rm -f ${containerPath}`, {
          stdio: ["ignore", "pipe", "pipe"],
        });
      }
    } else {
      console.log(`    ${PSQL_BECAUSE[because]}`);
      // Arguments go to psql directly, not through a shell, and the password through
      // PGPASSWORD, so a password holding `$` or a backtick reaches psql as written and
      // never shows in `ps`.
      try {
        execFileSync(
          "psql",
          [psql.url, "-v", "ON_ERROR_STOP=1", "-f", filePath],
          { stdio: ["ignore", "pipe", "inherit"], env: psql.env },
        );
      } catch (err) {
        throw psqlFailure(err, file);
      }
    }
  }
}

main();
